  'help.issueType': 'Muammo turi',
  'help.yourEmail': 'Sizning emailingiz',
  'help.describe': 'Muammoni ta\'riflang',
  'help.describePlaceholder': 'Nima bo\'lganini iloji boricha batafsil aytib bering...',
  'help.send': 'Ticketni Yuborish',
  'help.ticketSent': 'Ticket Yuborildi!',
  'help.ticketSentDesc': 'Sizning so\'rovingizni oldik. Jamoamiz 24 soat ichida email orqali javob beradi.',
  'help.close': 'Yopish',
  'help.ticketError': 'Ticketni yuborishda xato. Qayta urinib ko\'ring.',
  'help.type.cant_login': 'Kirishim mumkin emas',
  'help.type.email_issue': 'Email bilan muammo',
  'help.type.security': 'Xavfsizlik',
  'help.type.other': 'Boshqa',
  'help.faq.cantLogin.q': 'Hisobimga kira olmayapman',
  'help.faq.cantLogin.a': 'To\'g\'ri email va parolni ishlatayotganingizni tekshiring. Agar parolni unutgan bo\'lsangiz, kirish ekranida "Parolni unuttim?" tugmasini bosing. Agar muammo davom etsa, yordam ticketini yarating.',
  'help.faq.notReceiving.q': 'Email olmayapman',
  'help.faq.notReceiving.a': 'Avval Spam papkasini tekshiring. Saqlash joyingiz to\'lib qolmaganiga ishonch hosil qiling. Agar muammo davom etsa, jo\'natuvchining manzili to\'g\'ri ekanligini tasdiqlang va ticket yarating.',
  'help.faq.cantSend.q': 'Email yubora olmayapman',
  'help.faq.cantSend.a': 'Internet ulanishingizni va qabul qiluvchining manzilini tekshiring. Ilova hajmi 25MB dan oshmasligiga ishonch hosil qiling. Bir necha daqiqadan so\'ng qayta urinib ko\'ring.',
  'help.faq.forgotPassword.q': 'Parolni unuttim',
  'help.faq.forgotPassword.a': 'Kirish ekranida "Parolni unuttim?" tugmasini bosing va tiklash emaili orqali parolingizni qayta o\'rnating.',
  'help.faq.accountSecurity.q': 'Hisobim xavf ostida deb o\'ylayman',
  'help.faq.accountSecurity.a': 'Darhol parolingizni o\'zgartiring. Siz yubormagan xabarlarni jo\'natilganlar papkasida tekshiring. Xavfsizlik > Sozlamalar bo\'limida ikki bosqichli autentifikatsiyani yoqing. Zarur bo\'lsa, shoshilinch ticket yarating.',
  'help.faq.appAccess.q': 'Mobil telefonda appga qanday kiraman?',
  'help.faq.appAccess.a': 'Siz Chatyy ga chatyy.com.br orqali brauzerda kirishingiz yoki qurilmangizning ilovalar do\'konidan appimizni yuklab olishingiz mumkin.',
  'privacy.title': 'Maxfiylik Siyosati',
  'privacy.subtitle': 'Biz sizning ma\'lumotlaringizni qanday himoya qilamiz va ishlaymiz',
  'privacy.lastUpdated': 'Oxirgi yangilanish: Mart 2026',
  'privacy.dataCollection.title': 'Ma\'lumotlarni to\'plash',
  'privacy.dataCollection.body': 'Biz faqat email xizmatlari uchun zarur bo\'lgan ma\'lumotlarni to\'playmiz: ismingiz, email manzilingiz va yuborilgan va qabul qilingan xabarlar mazmuni. Biz sizning shaxsiy ma\'lumotlaringizni uchinchi shaxslarga marketing maqsadlarida sotmaymiz yoki ulashmaymiz.',
  'privacy.dataUsage.title': 'Ma\'lumotlaringizni qanday ishlatamiz',
  'privacy.dataUsage.body': 'Sizning ma\'lumotlaringiz email xizmatini boshqarish va yaxshilash uchun ishlatiladi, jumladan xabarlarni yetkazish, spamni filtrlash, AI funksiyalari (sizning roziligingiz bilan) va hisob xavfsizligi.',
  'privacy.dataSecurity.title': 'Ma\'lumotlar xavfsizligi',
  'privacy.dataSecurity.body': 'Biz barcha ma\'lumotlar uchun sanoat standartidagi shifrlash (TLS/SSL) dan foydalanamiz. Sessiyalar shifrlangan tokenlar va CSRF himoyasi bilan himoyalangan. Biz xavfsizlik amaliyotlarimizni muntazam ravishda tekshiramiz.',
  'privacy.cookies.title': 'Cookies va Mahalliy Saqlash',
  'privacy.cookies.body': 'Biz sessiyangizni saqlash, afzalliklaringizni (tema, til) eslab qolish va silliq tajriba taqdim etish uchun zarur cookies va mahalliy saqlashdan foydalanamiz. Biz uchinchi shaxslarning kuzatuv cookies laridan foydalanmaymiz.',
  'privacy.thirdParties.title': 'Uchinchi Tomon Xizmatlari',
  'privacy.thirdParties.body': 'Biz AI (Anthropic Claude) va push xabarnomalar kabi maxsus funksiyalar uchun uchinchi tomon xizmatlaridan foydalanishimiz mumkin. Ushbu xizmatlar o\'z maxfiylik siyosatlariga amal qiladi va faqat zarur bo\'lgan minimal ma\'lumotlarni qayta ishlaydi.',
  'privacy.rights.title': 'Sizning Huquqlaringiz',
  'privacy.rights.body': 'Siz har qanday vaqtda shaxsiy ma\'lumotlaringizga kirish, tuzatish, eksport qilish yoki o\'chirish huquqiga egasiz. Ma\'lumotlaringizni Sozlamalar bo\'limida yoki bizning qo\'llab-quvvatlash xizmatimiz bilan bog\'lanib boshqarishingiz mumkin.',
  'privacy.contact.title': 'Biz bilan Aloqa',
  'privacy.contact.body': 'Maxfiylik yoki ma\'lumotlar so\'rovlari bo\'yicha savollar uchun privacy@chatyy.com.br manziliga murojaat qiling. Biz 30 kun ichida javob beramiz.',
  'terms.title': 'Xizmat Shartlari',
  'terms.subtitle': 'Chatyy dan foydalanish bo\'yicha ko\'rsatmalar',
  'terms.lastUpdated': 'Oxirgi yangilanish: Mart 2026',
  'terms.acceptance.title': 'Shartlarga Rozilik',
  'terms.acceptance.body': 'Chatyy ga kirish yoki undan foydalanish orqali siz ushbu Xizmat Shartlariga rozilik bildirasiz. Agar ushbu shartlarning biron bir qismiga rozilik bildirmasangiz, xizmatdan foydalanmang.',
  'terms.services.title': 'Xizmatlar Tavsifi',
  'terms.services.body': 'Chatyy email orqali muloqot xizmatlarini taqdim etadi, jumladan email yuborish, qabul qilish va boshqarish, shuningdek AI funksiyalari, taqvim bilan integratsiya va videokonferensiya.',
  'terms.accounts.title': 'Foydalanuvchi Hisoblari',
  'terms.accounts.body': 'Siz o\'z ma\'lumotlaringizni xavfsizligini ta\'minlash uchun javobgarsiz. Parolingizni baham ko\'rmang va hisobingizga ruxsatsiz kirishga yo\'l qo\'ymang. Ushbu xizmatdan foydalanish uchun kamida 13 yoshda bo\'lishingiz kerak.',
  'terms.conduct.title': 'Qabul Qilingan Foydalanish',
  'terms.conduct.body': 'Siz xizmatdan spam, zararli dastur, phishing yoki har qanday noqonuniy kontent yuborish uchun foydalanmaslikka rozilik bildirasiz. Boshqa foydalanuvchilarning hisoblariga kirishga yoki xizmat infratuzilmasini to\'xtatishga harakat qilmang.',
  'terms.content.title': 'Kontent Mulkchilik',
  'terms.content.body': 'Siz xizmat orqali yaratgan va yuborgan barcha kontentga egalik qilasiz. Biz sizning email yoki ilovalar ustidan mulk huquqini da\'vo qilmaymiz. Biz xizmatni taqdim etish uchun zarur bo\'lsa, kontentni qayta ishlashimiz mumkin.',
  'terms.limitation.title': 'Mas\'uliyatni Cheklash',
  'terms.limitation.body': 'Chatyy "shunday" taqdim etiladi. Biz 99,9% mavjudlikni ta\'minlashga harakat qilamiz, lekin uzluksiz xizmatni kafolatlamaymiz. Xizmatdan foydalanish natijasida yuzaga keladigan bilvosita, tasodifiy yoki oqibatli zararlar uchun mas\'uliyatni o\'z zimmamizga olmaymiz.',
  'terms.termination.title': 'Hisobni Yopish',
  'terms.termination.body': 'Ushbu shartlarni buzgan hisoblarni to\'xtatish yoki yopishimiz mumkin. Siz har qanday vaqtda Sozlamalar bo\'limida hisobingizni o\'chirishingiz mumkin. Yopilgandan so\'ng, ma\'lumotlaringiz 30 kun ichida o\'chiriladi.',
  'terms.changes.title': 'Shartlarga O\'zgarishlar',
  'terms.changes.body': 'Biz ushbu shartlarni vaqt-vaqti bilan yangilashimiz mumkin. Muayyan o\'zgarishlar haqida email yoki appda xabarnoma orqali xabardor qilamiz. O\'zgarishlardan keyin davom etish shartlarni yangilangan holda qabul qilishni anglatadi.',
