  'plans.faqWhatIsPlus': 'Chatyy One nima?',
  'plans.faqWhatIsPlusAnswer': 'Bu Chatyy ning premium rejasidir, barcha suhbatlaringiz, rasmlaringiz va videolaringizni himoya qiladi. Chatyy One bilan, agar siz biror narsani xato o\'chirsangiz, 30 kun ichida qaytarib olishingiz mumkin. Bundan tashqari, siz 200GB saqlash, One AI shaxsiy yordamchi sifatida va 100MB gacha fayllarni yuborishingiz mumkin.',
  'plans.faqCancelAnswer': 'Sizning rejangiz to\'langan muddat oxirigacha faol bo\'ladi. Shundan so\'ng, bepul reja ga qaytasiz. 15GB dan ortiq bo\'lgan rasmlar va videolaringiz 30 kun davomida yuklab olish uchun saqlanadi.',
  'plans.faqHowFamily': 'Pro reja qanday ishlaydi?',
  'plans.faqHowFamilyAnswer': 'Siz o\'z oilangizdan 4 kishini qo\'shishingiz mumkin. Barchasi 500GB saqlashni bo\'lishadi va Chatyy One ning barcha foydalaridan foydalanishadi. Har bir kishi o\'z shaxsiy joyiga ega — hech kim boshqalarning fayllarini ko\'rmaydi.',
  'plans.faqChangePlanAnswer': 'Ha! Agar siz Plus dan Pro ga yangilasangiz, faqat farq miqdori olinadi. Agar siz pastga o\'tsangiz, hozirgi reja muddat oxirigacha davom etadi.',
  'plans.faqCardDeclined': 'Mening kartam rad etildi, nima qilishim kerak?',
  'plans.faqCardDeclinedAnswer': 'Sizda kartangizni yangilash uchun 7 kun bor. Ushbu davrda barcha foydalar davom etadi. 7 kundan so\'ng, reja bepulga qaytadi.',
