  'plans.faqDataSafeAnswer': 'Ha! Sizning to\'lov ma\'lumotlaringiz oxirgi nuqtaga qadar shifrlangan holda qayta ishlanadi. Biz sizning karta raqamingizni saqlamaymiz — faqat sizning ma\'lumotlaringiz uchun oxirgi 4 raqamini saqlaymiz.',
